entries[401119] = { ["name"] = "Lodernder Speer", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Jäger nimmt mehrere Spielercharaktere ins Visier und schleudert ' Lodernder Speer ' auf sie, was Spielercharakteren innerhalb von 6 Metern um den Einschlag sofort 238844 körperlichen Schaden zufügt.\n\n' Lodernder Speer ' verbleibt im Boden und explodiert kurz darauf, was allen Spielercharakteren innerhalb von 8 Metern 286504 Feuerschaden zufügt." }
entries[401122] = { ["name"] = "Halbmond", ["text"] = "Kanalisiert (Wirken in 3 sek.)\nAtmet in einem kegelförmigen Bereich magische Energie aus und verursacht Arkanschaden." }
entries[401123] = { ["name"] = "Wilder Klingensturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion belegt den Krieger 30 Sek. lang alle 6 Sek. mit ' Wilder Klingensturm ', wodurch dieser allen Spielercharakteren und Kreaturen innerhalb von 8 Metern 4 Sek. lang alle 1 Sek. 25 körperlichen Schaden zufügt." }
entries[401124] = { ["name"] = "Eifernde Hinrichtung", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion verderbt den Glauben des Paladins, was ihn 30 Sek. lang dazu zwingt, alle 6 Sek. einen Hammer aus dem Licht zu rufen. Der Hammer weiht den Boden und fügt allen Zielen im Effektbereich 10 Heiligschaden zu. Zusätzlich erleiden sie 50 Heiligschaden, wenn der Hammer nach 5 Sek. landet." }
entries[401125] = { ["name"] = "Verderbte Tiere", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion zwingt den Jäger, verderbte Begleiter herbeizurufen und angreifen zu lassen.\n\nNach Erlegen eines verderbten Begleiters wird der Jäger durch ' Entfesselte Dunkelheit ' ermächtigt." }
entries[401126] = { ["name"] = "Wilder Verrat", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion verderbt die natürliche Hinterhältigkeit des Schurken und zwingt ihn, alle 10 Sekunden durch die Schatten zu einem Verbündeten zu treten und dann Dolche auf alle Ziele innerhalb von 10 Metern zu werfen, die 20 körperlichen Schaden verursachen. Belegt alle Ziele zusätzlich mit ' Wildes Gift '." }
entries[401127] = { ["name"] = "Verzweifelter Schrei", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharions Verderbnis untergräbt den Glauben des Priesters, sodass 30 Sek. lang alle 6 Sek. ein ' Verzweifelter Schrei ' aus ihm hervorbricht, der Spielercharakteren und Kreaturen innerhalb von 8 Metern alle 1 Sek. 7 Schattenschaden zufügt und sie für 6 Sek. vor Furcht davonlaufen lässt.\n\nDer Priester erhält für jedes getroffene Ziel eine Anwendung von ' Schattenwort: Niedertracht ', bis zu einem Maximum von 5." }
entries[401128] = { ["name"] = "Wilder Griff", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion übernimmt die Macht des Untodes des Todesritters und zwingt ihn 30 Sek. lang, alle 10 Sek. Bereiche von ' Wilde Pestilenz ' zu erschaffen und Verbündete mit 'Todesgriff' zu sich heranzuziehen." }
entries[401129] = { ["name"] = "Totem des Schattenelementars", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion zwingt den Schamanen, Totems zu beschwören, um Schattenelementare zu binden, die danach angreifen.\n\nNach dem Sieg über einen Elementar wird der Schamane durch ' Entfesselte Dunkelheit ' ermächtigt." }
entries[401130] = { ["name"] = "Wilde Magie", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion verdirbt den Fluss der arkanen Energien im Magier, wodurch 30 Sek. lang alle 10 Sek. ' Wilde Magie ' aus ihm hervorbricht, was Spielercharakteren und Kreaturen innerhalb von 10 Metern 4 Sek. lang alle 0.5 Sek. 20 Arkanschaden zufügt." }
entries[401131] = { ["name"] = "Wilde Beschwörung", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion zwingt den Hexenmeister, Halluzinationen ausgehungerter Leerenbestien zu beschwören, die den Hexenmeister 25 Sek. lang angreifen.\n\nJedes Mal, wenn der Hexenmeister eine dieser Bestien tötet, wird er durch ' Entfesselte Dunkelheit ' ermächtigt." }
entries[401132] = { ["name"] = "Geister, Wasser und Verfall", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion verderbt die Essenz des Mönchs, wodurch Geister sich von ihm abspalten und ihn 30 Sek. lang angreifen.\n\nWenn der Mönch einen dieser Geister besiegt, wird er durch ' Entfesselte Dunkelheit ' ermächtigt." }
entries[401133] = { ["name"] = "Wilde Verwandlung", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion nutzt die Verbindung des Druiden zur Natur aus und zwingt ihn 30 Sek. lang, sich alle 10 Sek. in eine zufällige Gestalt zu verwandeln. Die wilde Gewalt der Verwandlung lässt den Druiden ' Wildes Hauen ' einsetzen und gewährt ihm ' Eifer des Gestaltwandlers '." }
entries[401134] = { ["name"] = "Chaostanz", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion zwingt den Dämonenjäger 30 Sek. lang, alle 6 Sek. in einen chaotischen Klingentanz auszubrechen, der allen Kreaturen und Spielercharakteren innerhalb von 8 Metern mehrfach 20 Chaosschaden zufügt." }
entries[401135] = { ["name"] = "Wilder Atem", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion übernimmt die Kontrolle über den Rufer und zwingt ihn 30 Sek. lang, alle 6 Sek. ' Wilder Atem ' zu wirken, was allen Spielercharakteren 10 Feuerschaden zufügt, während sie über das Schlachtfeld fliegen." }
