entries[402115] = { ["name"] = "Hallender Spalt", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeltharion zerschmettert den Boden unter sich und fügt Spielercharakteren innerhalb von 24 Metern um den Einschlag 1436238 Vulkanschaden sowie allen anderen Spielercharakteren zusätzlich 179065 Vulkanschaden zu. Dieser Effekt hallt an jedem bisherigen Ort wider, wenn ' Hallender Spalt ' eingesetzt wird.\n\nJeder Einsatz löst ' Eingestürzte Erde ' aus und verbreitet ' Sickernde Lava '." }
