entries[402600] = { ["name"] = "Massendesintegration", ["text"] = "300 Meter Reichweite\nSofort\nSarkareth formt ein schimmerndes Abbild, das Spielercharaktere markiert. Nach 6 Sek. stößt das Abbild Energie in einer Linie zu seinen Zielen aus, die 191002 Arkanschaden verursacht.\n\nWenn ' Massendesintegration ' ein Ziel mit ' Tyrannisierendes Heulen ' trifft, wird dieser Effekt entfernt und das Ziel mit ' Desintegriert ' belegt." }
