entries[402771] = { ["name"] = "Ätzende Verbrennung", ["text"] = "100 Meter Reichweite\nSofort\nDie automatischen Angriffe des Zaubernden verursachen 1 Min. lang alle 3 Sek. 9 Feuerschaden." }
entries[402772] = { ["name"] = "Entsetzliches Geschrei", ["text"] = "15 Meter Reichweite\nWirken in 2 sek. 12 sek. Abklingzeit\nFears the target for 5 Sek..\nReduces the movement speed of the target by 75% for 5 Sek..\nInflicts 20 Shadow damage to an enemy every 1 sec for 5 Sek.." }
entries[402775] = { ["name"] = "Rasende Stöße", ["text"] = "Wirken in 1 sek. 20 sek. Abklingzeit\nEntfesselt einen Hagel aus Angriffen und verursacht 3 Sek. lang alle 0.8 Sek. 30 körperlichen Schaden." }
entries[402776] = { ["name"] = "Rasende Stöße", ["text"] = "10 Meter Reichweite\nSofort\nEntfesselt einen Hagel aus Angriffen und verursacht 3 Sek. lang alle 0.8 Sek. 30 körperlichen Schaden." }
entries[402784] = { ["name"] = "Äonenerschütterung", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nChronikar wirft ihre Waffe auf die Siechende Sandlache , die ihr am nächsten ist, um dieser die Macht zu entziehen und ihr eigenes Angriffstempo 8 Sek. lang um 50% zu erhöhen.\n\nFügt allen Spielercharakteren innerhalb von 18 Metern um den Einschlag 50 Arkanschaden zu.\n\nDie Explosion zerschmettert die Lache in Äonenfragmente und lässt Äonenrückstände herabregnen." }
entries[402787] = { ["name"] = "Explosive Schläge", ["text"] = "Sofort\nDie automatischen Angriffe des Zaubernden fügen Gegnern innerhalb von 5 Metern um den Einschlagsort 25 Feuerschaden zu.\n(5s Abklingzeit)" }
entries[402793] = { ["name"] = "Feuerschlag", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nGholna schlägt auf ihr aktuelles Ziel ein, fügt Spielercharakteren innerhalb eines kegelförmigen Bereichs vor sich 65 Vulkanschaden zu und stößt sie zurück.\n\nBelegt von diesem Effekt getroffene Spielercharaktere außerdem mit ' Brennende Berührung '." }
entries[402795] = { ["name"] = "Feuerschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nGholna schlägt auf ihr aktuelles Ziel ein, fügt Spielercharakteren innerhalb eines kegelförmigen Bereichs vor sich 129026 Vulkanschaden zu und stößt sie zurück.\n\nBelegt von diesem Effekt getroffene Spielercharaktere außerdem mit ' Brennende Berührung '." }
entries[402797] = { ["name"] = "Explosive Schläge", ["text"] = "8 Meter Reichweite\nSofort\nDie automatischen Angriffe des Zaubernden fügen Gegnern innerhalb von 5 Metern um den Einschlagsort 25 Feuerschaden zu." }
entries[402798] = { ["name"] = "Kristallisieren", ["text"] = "Sofort\nDie automatischen Angriffe des Zaubernden belegen das Ziel mit 'Kristallisieren'. 'Kristallisieren' verursacht alle 2 Sek. 5 Arkanschaden und verringert den erlittenen körperlichen Schaden um 5% sowie die Bewegungsgeschwindigkeit um 10%. Hält 10 Sek. lang an. Dieser Effekt ist stapelbar.\n\nDer Effekt wird durch ' Zertrümmernder Stachel ' entfernt." }
entries[402800] = { ["name"] = "Zertrümmernder Stachel", ["text"] = "20 Meter Reichweite\nWirken in 2 sek.\nSchleudert zertrümmernde Stachel auf Gegner, fügt ihnen 150 körperlichen Schaden zu und entfernt ' Kristallisieren '." }
entries[402805] = { ["name"] = "Zertrümmernder Stachel" }
entries[402807] = { ["name"] = "Zertrümmernder Stachel", ["text"] = "Wirken in 1 sek. 11 sek. Abklingzeit\nSchleudert zertrümmernde Stachel auf Gegner, fügt ihnen 150 körperlichen Schaden zu und entfernt ' Kristallisieren '." }
entries[402812] = { ["name"] = "Zersetzende Energie", ["text"] = "Sofort\nDie Berührung der durch ' Massendesintegration ' hinterlassenen magischen Rückstände verursacht alle 1 Sek. 31 Arkanschaden und verringert die Bewegungsgeschwindigkeit um 50%." }
entries[402813] = { ["name"] = "Feuriger Gezeitenstein", ["text"] = "Schwimmt mit dem Strom, der alle 30 Sek. zu Hochwasser ansteigt oder zu Niedrigwasser absinkt.\n\nBei Niedrigwasser gewährt Euch Euer nächster offensiver Zauber oder Eure nächste Distanzfähigkeit 12 Sek. lang 123 kritischen Trefferwert.\n\nBei Hochwasser löst Euer nächster offensiver Zauber oder Eure nächste Distanzfähigkeit eine Lavawelle aus, die über Eurem Ziel bricht und 1690 Vulkanschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird. Dieser Schaden ist verringert, wenn die Lavawelle weniger als 20 Meter weit reicht." }
entries[402814] = { ["name"] = "Totem des Schattenelementars", ["text"] = "Unbegrenzte Reichweite\nWirken in 5 sek.\nNeltharion zwingt den Schamanen, Totems zu beschwören, um Schattenelementare zu binden, die danach angreifen.\n\nNach dem Sieg über einen Elementar wird der Schamane durch ' Entfesselte Dunkelheit ' ermächtigt." }
entries[402815] = { ["name"] = "Zersetzende Energie", ["text"] = "200 Meter Reichweite\nSofort\nDie Berührung der durch ' Massendesintegration ' hinterlassenen magischen Rückstände verursacht alle 1 Sek. 31 Arkanschaden und verringert die Bewegungsgeschwindigkeit um 50%." }
