entries[402819] = { ["name"] = "Kristallisieren", ["text"] = "100 Meter Reichweite\nSofort\nDie automatischen Angriffe des Zaubernden belegen das Ziel mit 'Kristallisieren'. 'Kristallisieren' verursacht alle 2 Sek. 5 Arkanschaden und verringert den erlittenen körperlichen Schaden um 5% sowie die Bewegungsgeschwindigkeit um 10%. Hält 10 Sek. lang an. Dieser Effekt ist stapelbar.\n\nDer Effekt wird durch ' Zertrümmernder Stachel ' entfernt." }
entries[402822] = { ["name"] = "Lavawelle", ["text"] = "100 Meter Reichweite\nSofort\nSchwimmt mit dem Strom, der alle 30 Sek. zu Hochwasser ansteigt oder zu Niedrigwasser absinkt.\n\nBei Niedrigwasser gewährt Euch Euer nächster offensiver Zauber oder Eure nächste Distanzfähigkeit 12 Sek. lang 123 kritischen Trefferwert.\n\nBei Hochwasser löst Euer nächster offensiver Zauber oder Eure nächste Distanzfähigkeit eine Lavawelle aus, die über Eurem Ziel bricht und 1690 Vulkanschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird. Dieser Schaden ist verringert, wenn die Lavawelle weniger als 20 Meter weit reicht." }
entries[402824] = { ["name"] = "Brennende Berührung", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht 36 Sek. lang alle 2 Sek. 3970 Vulkanschaden. Dieser Effekt ist stapelbar.\n\nZerstreut außerdem ' Sengender Wirbelsturm ', wenn ein Spielercharakter darin steht." }
