entries[402914] = { ["name"] = "Unersättliche Verfolgung", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nDie unersättlichen Flammen suchen nach Machtquellen in der Nähe, um ihren Hunger danach zu stillen..." }
entries[402916] = { ["name"] = "Rechtschaffene Sache", ["text"] = "Sofort\n'Letztes Urteil' hat eine Chance von 100%, die Abklingzeit von 'Klinge der Gerechtigkeit' abzuschließen." }
entries[402928] = { ["name"] = "Sturmerfüllter Stein", ["text"] = "Ca. 2.25 Procs pro Minute\nWird einem Gegner ein kritischer Treffer zugefügt, besteht die Chance, dass er und 2 Gegner in der Nähe geschockt werden und 388 Naturschaden erleiden." }
entries[402929] = { ["name"] = "Widerhallender Donnerstein", ["text"] = "Bewegung baut eine elektrische Ladung auf, wodurch Eure nächste Schadensfähigkeit außerdem 502 Naturschaden verursacht." }
entries[402930] = { ["name"] = "Feuergeküsster Stein", ["text"] = "Ca. 2.5 Procs pro Minute\nBeim Verursachen von Schaden besteht eine Chance, dass der Gegner in Brand gesteckt wird und 86 Feuerschaden im Verlauf von 7 Sek. erleidet." }
entries[402931] = { ["name"] = "Tobender Magmastein", ["text"] = "Ca. 2.5 Procs pro Minute\nBeim Absorbieren von Schaden besteht eine Chance, dass Ihr mit Lava umhüllt werdet, sodass Nahkampfangreifer 6 Sek. lang 84 Feuerschaden erleiden." }
entries[402932] = { ["name"] = "Sengender Rauchstein", ["text"] = "Bei erfolgreichen Unterbrechungen wird Rauch freigesetzt und fügt Gegnern innerhalb eines kegelförmigen Bereichs von 8 Metern vor Euch 287 Feuerschaden zu.\n(1s Abklingzeit)" }
entries[402934] = { ["name"] = "Entropischer Teufelsstein", ["text"] = "Der durch urzeitliche Steine verursachte Feuerschaden wird um 60% erhöht und zu Chaosschaden." }
entries[402935] = { ["name"] = "Unbeugsamer Erdstein", ["text"] = "Ca. 2 Procs pro Minute\nBeim Erleiden von Feuerschaden besteht die Chance, dass Ihr Euch in einen Schild hüllt und 12 Sek. lang 1884 Schaden absorbiert." }
entries[402936] = { ["name"] = "Glänzender Obsidianstein", ["text"] = "Beim Erhalten eines Absorptionsschild durch einen urzeitlichen Stein bricht der Boden auf und fügt Gegnern innerhalb von 5 Metern 783 körperlichen Schaden zu." }
entries[402938] = { ["name"] = "Schimmernder Eisenstein", ["text"] = "Wenn Ihr Euch im Kampf 3 Sek. lang nicht bewegt, wächst Eure Entschlossenheit, was 942 Schaden absorbiert und den Schaden Eurer automatischen Angriffe 12 Sek. lang um 28 erhöht." }
entries[402939] = { ["name"] = "Überschwemmender Wasserstein", ["text"] = "Ca. 2.5 Procs pro Minute\nFähigkeiten haben eine Chance, einen Verbündeten in der Nähe zu durchnässen, was ihn im Verlauf von 6 Sek. um 251 Gesundheit heilt." }
entries[402940] = { ["name"] = "Gefrierender Eisstein", ["text"] = "Ca. 2.5 Procs pro Minute\nBeim Verursachen von Schaden besteht eine Chance, den Gegner zu unterkühlen, was ihm 562 Frostschaden zufügt und ihn für 6 Sek. um 0% verlangsamt." }
entries[402941] = { ["name"] = "Kalter Froststein", ["text"] = "Gewährt alle 20 Sek. einen Frostschild, der 1256 Schaden absorbiert und Nahkampfangreifer für 5 Sek. um 15% verlangsamt." }
entries[402942] = { ["name"] = "Kondensierender Dampfstein", ["text"] = "Ca. 3 Procs pro Minute\nBeim Erhalten von Heilung besteht eine Chance, Dampf freizusetzen, der bei Euch sowie 2 Verbündeten in der Nähe 623 Gesundheit wiederherstellt." }
entries[402943] = { ["name"] = "Funkelnder Manastein", ["text"] = "Frosteffekte durch urzeitliche Steine stellen im Verlauf von 3 Sek. insgesamt ( 36 * 3) Mana wieder her." }
entries[402944] = { ["name"] = "Wirbelnder Mojostein", ["text"] = "In der Nähe einer sterbenden Kreatur wird ihr ein Teil ihres Mojo entzogen, das letztendlich kristallisiert." }
entries[402947] = { ["name"] = "Summender Arkanstein", ["text"] = "Ca. 2 Procs pro Minute\nBeim Verursachen von Magieschaden besteht eine Chance, für jede ausgerüstete Art urzeitlicher Steine arkane Geschosse abzufeuern.\n(20s Abklingzeit)" }
entries[402948] = { ["name"] = "Harmonischer Musikstein", ["text"] = "Erhöht bei Kampfbeginn Eure tertiären Werte und die von 4 Verbündeten in der Nähe 8 Sek. lang um 40 ." }
entries[402949] = { ["name"] = "Wilder Geisterstein", ["text"] = "Natur- und Heileffekte durch urzeitliche Steine stellen bei 5 Verbündeten in der Nähe im Verlauf von 7 Sek. ( 45 * 7) Gesundheit wieder her." }
entries[402951] = { ["name"] = "Nekromantischer Todesstein", ["text"] = "Einmal pro Minute gewährt Bewegung in der Nähe einer Leiche 25 Sek. Sek. lang die Ausrüstungseffekte der begehrlichen Blut-, kalten Frost- und pestilenten Seuchensteine.\n\nIst einer dieser Effekte bereits aktiv, erhöht sich seine Wirksamkeit um 75%." }
entries[402952] = { ["name"] = "Pestilenter Seuchenstein", ["text"] = "Ca. 2.5 Procs pro Minute\nBeim Verursachen von Schaden kann das Ziel mit einer Seuche infiziert werden, die sich zu nahen Gegnern ausbreitet und im Verlauf von 9 Sek. ( 37 * 9) Naturschaden verursacht." }
entries[402955] = { ["name"] = "Unergründlicher Pastellstein", ["text"] = "Ca. 4.5 Procs pro Minute\nBei Zaubern und Fähigkeiten besteht eine Chance, einen zufälligen Effekt eines urzeitlichen Steins auszulösen." }
entries[402957] = { ["name"] = "Begehrlicher Blutstein", ["text"] = "Ca. 2.25 Procs pro Minute\nBeim Verursachen von Schaden besteht eine Chance, Leben zu entziehen, was 446 Schattenschaden verursacht und Euch in Höhe des verursachten Schadens heilt." }
entries[402959] = { ["name"] = "Prophetischer Zwielichtstein", ["text"] = "Schadenseffekte Eurer urzeitlichen Steine lösen einen Eurer Heileffekte aus und umgekehrt." }
